  "crypto/md5"
  "crypto/sha1"
  "crypto/sha256"
  "crypto/sha512"
  "encoding/hex"
  "fmt"
)

type sample struct{pwd, hex string}
var samples = []sample{
  {"a","67843e85e28c0d75473ff8fbebd1b81c1e0c"},
  {"aa","dfc4d1dfeefc819233b55f559a2216f3fc01"},
  {"aaa","56a70093cbea2d8247c273b7cfbc408c3ad0"},
  {"aaaa","3d0f0a9bd61dd9d0aea7190deaf4eb64e14f"},
  {"password","7e6bfd344c4a4828647a909db82d62f2d6b2"},
  {"passw0rd","c914b686d3b8f41e2ad153ea091d081d4d4a"},
  {"SECRET","9ab56b847c128a7984bb39cc9983b9cb821b"},
  {"secret","e8008b37b17970377b105efae1e8d5783107"},
  {"secret1","9e5b729622d8850c85252cd7bfe2599a397d"},
  {"12345678","bfd0d38fe98a3ffce9b5944863e6291f2ab3"},
  {"1234567890","2fbb89843e88b6ea2d7ee36dafef38baeca7"},
}

type keygen struct{name string; fn func(string) []byte}

func zpad(n int) func(string) []byte {
  return func(s string) []byte {
    b := make([]byte, n)
    copy(b, []byte(s))
    return b
  }
}
func repeat(n int) func(string) []byte {
  return func(s string) []byte {
    b := make([]byte, n)
    sb := []byte(s)
    for i := 0; i < n; i++ { b[i] = sb[i%len(sb)] }
    return b
  }
}
func truncHash(h func([]byte) []byte, n int) func(string) []byte {
  return func(s string) []byte {
    b := h([]byte(s))
    return append([]byte(nil), b[:n]...)
  }
}
func md5h(b []byte) []byte { sum := md5.Sum(b); return sum[:] }
func sha1h(b []byte) []byte { sum := sha1.Sum(b); return sum[:] }
func sha256h(b []byte) []byte { sum := sha256.Sum256(b); return sum[:] }
func sha512h(b []byte) []byte { sum := sha512.Sum512(b); return sum[:] }

func decryptCTR(key, data []byte) ([]byte, error) {
  block, err := aes.NewCipher(key); if err != nil { return nil, err }
  out := make([]byte, len(data))
  iv := make([]byte, aes.BlockSize)
  cipher.NewCTR(block, iv).XORKeyStream(out, data)
  return out, nil
}
func decryptCFB(key, data []byte) ([]byte, error) {
  block, err := aes.NewCipher(key); if err != nil { return nil, err }
  out := make([]byte, len(data))
  iv := make([]byte, aes.BlockSize)
  cipher.NewCFBDecrypter(block, iv).XORKeyStream(out, data)
  return out, nil
}
func decryptOFB(key, data []byte) ([]byte, error) {
  block, err := aes.NewCipher(key); if err != nil { return nil, err }
  out := make([]byte, len(data))
  iv := make([]byte, aes.BlockSize)
  cipher.NewOFB(block, iv).XORKeyStream(out, data)
  return out, nil
}
func decryptCBC16(key, data []byte) ([]byte, error) {
  if len(data) < 16 { return nil, fmt.Errorf("short") }
  block, err := aes.NewCipher(key); if err != nil { return nil, err }
  out := make([]byte, 16)
  iv := make([]byte, aes.BlockSize)
  cipher.NewCBCDecrypter(block, iv).CryptBlocks(out, data[:16])
  return out, nil
}
func decryptECB16(key, data []byte) ([]byte, error) {
  if len(data) < 16 { return nil, fmt.Errorf("short") }
  block, err := aes.NewCipher(key); if err != nil { return nil, err }
  out := make([]byte, 16)
  block.Decrypt(out, data[:16])
  return out, nil
}

func allSame(xs [][]byte) bool {
  if len(xs) == 0 { return true }
  first := string(xs[0])
  for _, x := range xs[1:] {
    if string(x) != first { return false }
  }
  return true
}

func main() {
  keygens := []keygen{
    {"zpad16", zpad(16)}, {"zpad24", zpad(24)}, {"zpad32", zpad(32)},
    {"repeat16", repeat(16)}, {"repeat24", repeat(24)}, {"repeat32", repeat(32)},
    {"md5", truncHash(md5h, 16)},
    {"sha1_16", truncHash(sha1h, 16)}, {"sha1_24", truncHash(sha1h, 24)},
    {"sha256_16", truncHash(sha256h, 16)}, {"sha256_24", truncHash(sha256h, 24)}, {"sha256_32", truncHash(sha256h, 32)},
    {"sha512_16", truncHash(sha512h, 16)}, {"sha512_24", truncHash(sha512h, 24)}, {"sha512_32", truncHash(sha512h, 32)},
  }
  modes := []struct{
    name string
    fn func([]byte, []byte) ([]byte, error)
  }{
    {"ctr0", decryptCTR}, {"cfb0", decryptCFB}, {"ofb0", decryptOFB}, {"cbc0_16", decryptCBC16}, {"ecb16", decryptECB16},
  }
  for _, kg := range keygens {
    for _, mode := range modes {
      var outs [][]byte
      ok := true
      for _, s := range samples {
        data, _ := hex.DecodeString(s.hex)
        out, err := mode.fn(kg.fn(s.pwd), data)
        if err != nil { ok = false; break }
        outs = append(outs, out)
      }
      if ok && allSame(outs) {
        fmt.Printf("MATCH key=%s mode=%s plain=%x\n", kg.name, mode.name, outs[0])
      }
    }
  }
}
