+func ScanRepository(cfg Config) (*Repository, error) {
+	format, err := compileLogNameFormat(cfg.LogNameFormat)
+	if err != nil {
+		return nil, err
+	}
+	repo := &Repository{Entries: map[string]*LogEntry{}}
+
+	dirEntries, err := os.ReadDir(cfg.LogDirPath)
+	if err != nil {
+		return repo, nil
+	}
+
+	for _, dirEntry := range dirEntries {
+		if dirEntry.IsDir() {
+			continue
+		}
+		date, ok := format.Parse(dirEntry.Name())
+		if !ok {
+			continue
+		}
+		path := filepath.Join(cfg.LogDirPath, dirEntry.Name())
+		contentBytes, err := os.ReadFile(path)
+		if err != nil {
+			continue
+		}
+		entry := parseLogEntry(date, path, string(contentBytes), cfg.FirstLineSection)
+		repo.Entries[dateKey(date)] = entry
+		repo.Dates = append(repo.Dates, date)
+	}
+
+	sort.Slice(repo.Dates, func(i, j int) bool {
+		return repo.Dates[i].Before(repo.Dates[j])
+	})
+	return repo, nil
+}
+
+func parseLogEntry(date time.Time, path, content string, firstLineSection bool) *LogEntry {
+	entry := &LogEntry{
+		Date:               date,
+		Path:               path,
+		Content:            content,
+		SectionOccurrences: map[string]int{},
+	}
+
+	currentSection := ""
+	sectionSeen := map[string]bool{}
+	scanner := bufio.NewScanner(strings.NewReader(content))
+	lineIndex := 0
+	for scanner.Scan() {
+		line := scanner.Text()
+		trimmed := strings.TrimSpace(line)
+		if trimmed == "" {
+			lineIndex++
+			continue
+		}
+
+		if isSectionHeading(trimmed) {
+			if !(lineIndex == 0 && !firstLineSection) {
+				currentSection = strings.TrimSpace(strings.TrimLeft(trimmed, "#"))
+				sectionSeen[currentSection] = true
+				if entry.SectionOccurrences[currentSection] == 0 {
+					entry.SectionOccurrences[currentSection] = 1
+				}
+				lineIndex++
+				continue
+			}
+		}
+
+		if strings.HasPrefix(trimmed, "* ") {
+			tagName := normalizeTagName(strings.TrimSpace(trimmed[2:]))
+			entry.TagOccurrences = append(entry.TagOccurrences, TagOccurrence{
+				Section: currentSection,
+				Name:    tagName,
+			})
+			entry.SectionOccurrences[currentSection]++
+		}
+
+		lineIndex++
+	}
+
+	for sectionName := range sectionSeen {
+		if entry.SectionOccurrences[sectionName] == 0 {
+			entry.SectionOccurrences[sectionName] = 1
+		}
+	}
+	return entry
+}
+
+func isSectionHeading(line string) bool {
+	if !strings.HasPrefix(line, "#") {
+		return false
+	}
+	hashes := 0
+	for hashes < len(line) && line[hashes] == '#' {
+		hashes++
+	}
+	return hashes < len(line) && line[hashes] == ' '
+}
+
+func normalizeTagName(raw string) string {
+	depth := 0
+	cut := len(raw)
+	for index, char := range raw {
+		switch char {
+		case '(':
+			depth++
+		case ')':
+			if depth > 0 {
+				depth--
+			}
+		case ':':
+			if depth == 0 {
+				cut = index
+				goto done
+			}
+		}
+	}
+done:
+	return strings.TrimSpace(raw[:cut])
+}
+
+func compileLogNameFormat(raw string) (LogNameFormat, error) {
+	var layout strings.Builder
+	var regex strings.Builder
+	regex.WriteString("^")
+	var tokens []formatToken
+
+	for index := 0; index < len(raw); index++ {
+		char := raw[index]
+		if char != '%' {
+			layout.WriteByte(char)
+			regex.WriteString(regexp.QuoteMeta(string(char)))
+			continue
+		}
+		if index+1 >= len(raw) {
+			return LogNameFormat{}, fmt.Errorf("invalid log-name-format")
+		}
+		index++
+		switch raw[index] {
+		case '%':
+			layout.WriteByte('%')
+			regex.WriteString("%")
+		case 'Y':
+			layout.WriteString("2006")
+			regex.WriteString("(\\d{4})")
+			tokens = append(tokens, formatToken{Name: "Y"})
+		case 'y':
+			layout.WriteString("06")
+			regex.WriteString("(\\d{2})")
+			tokens = append(tokens, formatToken{Name: "y"})
+		case 'm':
+			layout.WriteString("01")
+			regex.WriteString("(\\d{2})")
+			tokens = append(tokens, formatToken{Name: "m"})
+		case 'd':
+			layout.WriteString("02")
+			regex.WriteString("(\\d{2})")
+			tokens = append(tokens, formatToken{Name: "d"})
+		default:
+			layout.WriteByte('%')
+			layout.WriteByte(raw[index])
+			regex.WriteString(regexp.QuoteMeta("%" + string(raw[index])))
+		}
+	}
+
+	regex.WriteString("$")
+	compiled, err := regexp.Compile(regex.String())
+	if err != nil {
+		return LogNameFormat{}, err
+	}
+
+	return LogNameFormat{
+		raw:      raw,
+		goLayout: layout.String(),
+		regex:    compiled,
+		tokens:   tokens,
+	}, nil
+}
+
+func (format LogNameFormat) Format(date time.Time) string {
+	return date.Format(format.goLayout)
+}
+
+func (format LogNameFormat) Parse(name string) (time.Time, bool) {
+	matches := format.regex.FindStringSubmatch(name)
+	if matches == nil {
+		return time.Time{}, false
+	}
+
+	year := 0
+	month := 1
+	day := 1
+	groupIndex := 1
+	for _, token := range format.tokens {
+		value := matches[groupIndex]
+		groupIndex++
+		switch token.Name {
+		case "Y":
+			parsed, err := strconv.Atoi(value)
+			if err != nil {
+				return time.Time{}, false
+			}
+			year = parsed
+		case "y":
+			parsed, err := strconv.Atoi(value)
+			if err != nil {
+				return time.Time{}, false
+			}
+			if parsed >= 70 {
+				year = 1900 + parsed
+			} else {
+				year = 2000 + parsed
+			}
+		case "m":
+			parsed, err := strconv.Atoi(value)
+			if err != nil {
+				return time.Time{}, false
+			}
+			month = parsed
+		case "d":
+			parsed, err := strconv.Atoi(value)
+			if err != nil {
+				return time.Time{}, false
+			}
+			day = parsed
+		}
+	}
+	if year == 0 {
+		return time.Time{}, false
+	}
+
+	date := time.Date(year, time.Month(month), day, 12, 0, 0, 0, time.Local)
+	if date.Year() != year || int(date.Month()) != month || date.Day() != day {
+		return time.Time{}, false
+	}
+	return date, true
+}
+
+func dateKey(date time.Time) string {
+	return date.Format("2006-01-02")
