package main

import (
	"bufio"
	"bytes"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"syscall"
	"time"
	"unicode/utf8"
	"unsafe"
)

var errAppExit = errors.New("app exit")

type FocusArea int

const (
	FocusSections FocusArea = iota
	FocusTags
	FocusMain
)

type App struct {
	cfg             Config
	format          LogNameFormat
	repo            *Repository
	focus           FocusArea
	displayYear     int
	cursorDate      time.Time
	sectionItems    []MenuItem
	tagItems        []MenuItem
	sectionIndex    int
	tagIndex        int
	scratchpadMode  bool
	screen          *TerminalSession
}

func NewApp(cfg Config, repo *Repository) *App {
	format, err := compileLogNameFormat(cfg.LogNameFormat)
	if err != nil {
		panic(err)
	}
	now := time.Now().In(time.Local)
	app := &App{
		cfg:         cfg,
		format:      format,
		repo:        repo,
		focus:       FocusSections,
		displayYear: now.Year(),
		cursorDate:  time.Date(now.Year(), now.Month(), now.Day(), 12, 0, 0, 0, time.Local),
	}
	app.rebuildMenus()
	return app
}

func (app *App) Run() error {
	if isTerminal(os.Stdin.Fd()) && isTerminal(os.Stdout.Fd()) {
		session, err := NewTerminalSession(int(os.Stdin.Fd()), os.Stdout)
		if err != nil {
			return err
		}
		app.screen = session
		defer session.Close()
	} else {
		fmt.Fprint(os.Stdout, app.renderFrame(120, 30))
		return nil
	}

	reader := bufio.NewReader(os.Stdin)
	if err := app.redraw(); err != nil {
		return err
	}

	for {
		key, err := readKey(reader)
		if err != nil {
			return nil
		}
		if exit := app.handleKey(key); exit {
			return errAppExit
		}
		if err := app.redraw(); err != nil {
			return err
		}
	}
}

func (app *App) handleKey(key Key) bool {
	switch key.Kind {
	case KeyCtrlC, KeyQuit:
		return true
	case KeyTab:
		app.focus = (app.focus + 1) % 3
	case KeyBackTab:
		if app.focus == 0 {
			app.focus = 2
		} else {
			app.focus--
		}
	case KeyToggleScratchpad:
		app.scratchpadMode = !app.scratchpadMode
	case KeyNextYear:
		app.displayYear++
		app.cursorDate = time.Date(app.displayYear, app.cursorDate.Month(), minInt(app.cursorDate.Day(), daysInMonth(app.displayYear, app.cursorDate.Month())), 12, 0, 0, 0, time.Local)
		app.rebuildMenus()
	case KeyPrevYear:
		app.displayYear--
		app.cursorDate = time.Date(app.displayYear, app.cursorDate.Month(), minInt(app.cursorDate.Day(), daysInMonth(app.displayYear, app.cursorDate.Month())), 12, 0, 0, 0, time.Local)
		app.rebuildMenus()
	case KeyResetToday:
		now := time.Now().In(time.Local)
		app.displayYear = now.Year()
		app.cursorDate = time.Date(now.Year(), now.Month(), now.Day(), 12, 0, 0, 0, time.Local)
		app.rebuildMenus()
	case KeyDelete:
		if !app.scratchpadMode && app.focus == FocusMain {
			_ = os.Remove(app.currentLogPath())
			_ = app.refresh()
		}
	case KeyEnter:
		if app.scratchpadMode {
			_ = app.openEditor(app.scratchpadPath())
			_ = app.refresh()
		} else if app.focus == FocusMain {
			_ = app.openEditor(app.currentLogPath())
			_ = app.refresh()
		}
	case KeyUp:
		app.navigateUp()
	case KeyDown:
		app.navigateDown()
	case KeyLeft:
		app.navigateLeft()
	case KeyRight:
		app.navigateRight()
	}

	return false
}

func (app *App) navigateUp() {
	switch {
	case app.scratchpadMode:
		return
	case app.focus == FocusSections:
		if app.sectionIndex > 0 {
			app.sectionIndex--
			app.tagIndex = 0
			app.rebuildMenus()
		}
	case app.focus == FocusTags:
		if app.tagIndex > 0 {
			app.tagIndex--
		}
	case app.focus == FocusMain:
		app.cursorDate = app.cursorDate.AddDate(0, 0, -7)
		app.displayYear = app.cursorDate.Year()
		app.rebuildMenus()
	}
}

func (app *App) navigateDown() {
	switch {
	case app.scratchpadMode:
		return
	case app.focus == FocusSections:
		if app.sectionIndex+1 < len(app.sectionItems) {
			app.sectionIndex++
			app.tagIndex = 0
			app.rebuildMenus()
		}
	case app.focus == FocusTags:
		if app.tagIndex+1 < len(app.tagItems) {
			app.tagIndex++
		}
	case app.focus == FocusMain:
		app.cursorDate = app.cursorDate.AddDate(0, 0, 7)
		app.displayYear = app.cursorDate.Year()
		app.rebuildMenus()
	}
}

func (app *App) navigateLeft() {
	if app.scratchpadMode {
		return
	}
	if app.focus == FocusMain {
		app.cursorDate = app.cursorDate.AddDate(0, 0, -1)
		app.displayYear = app.cursorDate.Year()
		app.rebuildMenus()
	}
}

func (app *App) navigateRight() {
	if app.scratchpadMode {
		return
	}
	if app.focus == FocusMain {
		app.cursorDate = app.cursorDate.AddDate(0, 0, 1)
		app.displayYear = app.cursorDate.Year()
		app.rebuildMenus()
	}
}

func (app *App) refresh() error {
	repo, err := ScanRepository(app.cfg)
	if err != nil {
		return err
	}
	app.repo = repo
	app.rebuildMenus()
	return nil
}

func (app *App) selectedSectionValue() string {
	if len(app.sectionItems) == 0 || app.sectionIndex == 0 {
		return ""
	}
	return app.sectionItems[app.sectionIndex].Value
}

func (app *App) selectedTagValue() string {
	if len(app.tagItems) == 0 || app.tagIndex == 0 {
		return ""
	}
	return app.tagItems[app.tagIndex].Value
}

func (app *App) rebuildMenus() {
	app.sectionItems = app.buildSectionItems()
	if app.sectionIndex >= len(app.sectionItems) {
		app.sectionIndex = 0
	}
	app.tagItems = app.buildTagItems()
	if app.tagIndex >= len(app.tagItems) {
		app.tagIndex = 0
	}
}

func (app *App) buildSectionItems() []MenuItem {
	counts := map[string]int{}
	for _, date := range app.repo.Dates {
		if date.Year() != app.displayYear {
			continue
		}
		entry := app.repo.Entries[dateKey(date)]
		for section, count := range entry.SectionOccurrences {
			counts[section] += count
		}
	}

	items := []MenuItem{{Label: selectNoneLabel}}
	var sectionNames []string
	for section := range counts {
		sectionNames = append(sectionNames, section)
	}
	sort.Slice(sectionNames, func(i, j int) bool {
		if counts[sectionNames[i]] != counts[sectionNames[j]] {
			return counts[sectionNames[i]] > counts[sectionNames[j]]
		}
		return sectionNames[i] < sectionNames[j]
	})
	for _, section := range sectionNames {
		label := section
		if label == "" {
			label = rootSectionLabel
		}
		items = append(items, MenuItem{
			Label: label,
			Count: counts[section],
			Value: section,
		})
	}
	return items
}

func (app *App) buildTagItems() []MenuItem {
	section := app.selectedSectionValue()
	counts := map[string]int{}
	for _, date := range app.repo.Dates {
		if date.Year() != app.displayYear {
			continue
		}
		entry := app.repo.Entries[dateKey(date)]
		for _, tag := range entry.TagOccurrences {
			if section != "" && tag.Section != section {
				continue
			}
			counts[tag.Name]++
		}
	}

	items := []MenuItem{{Label: selectNoneLabel}}
	var tagNames []string
	for name := range counts {
		tagNames = append(tagNames, name)
	}
	sort.Slice(tagNames, func(i, j int) bool {
		if counts[tagNames[i]] != counts[tagNames[j]] {
			return counts[tagNames[i]] > counts[tagNames[j]]
		}
		return tagNames[i] < tagNames[j]
	})
	for _, name := range tagNames {
		items = append(items, MenuItem{
			Label: name,
			Count: counts[name],
			Value: name,
		})
	}
	return items
}

func (app *App) redraw() error {
	width, height := app.screen.Size()
	frame := app.renderFrame(width, height)
	return app.screen.Draw(frame)
}

func (app *App) renderFrame(width, height int) string {
	if width < 80 {
		width = 80
	}
	if height < 24 {
		height = 24
	}

	leftWidth := minInt(40, maxInt(34, width/3))
	rightWidth := maxInt(40, width-leftWidth-1)
	topHeight := minInt(24, maxInt(18, height-6))
	menuHeight := minInt(12, topHeight-5)
	eventsHeight := maxInt(5, topHeight-menuHeight)
	previewHeight := maxInt(5, height-topHeight-1)

	sectionsWidth := leftWidth / 2
	tagsWidth := leftWidth - sectionsWidth

	sectionsLines := app.renderMenuBox("Sections", sectionsWidth, menuHeight, app.sectionItems, app.sectionIndex, app.focus == FocusSections && !app.scratchpadMode)
	tagsLines := app.renderMenuBox("Tags", tagsWidth, menuHeight, app.tagItems, app.tagIndex, app.focus == FocusTags && !app.scratchpadMode)
	eventsLines := app.renderEventsBox(leftWidth, eventsHeight)
	leftLines := append(joinHorizontal(sectionsLines, tagsLines), eventsLines...)

	calendarLines := app.renderCalendarArea(rightWidth, topHeight)
	topLines := joinHorizontal(leftLines, calendarLines)
	previewLines := app.renderPreviewBox(width, previewHeight)

	var out strings.Builder
	header := fmt.Sprintf("       Today is: %s.  | There are %d log entries for year %d.", app.todayString(), app.logEntryCountForYear(app.displayYear), app.displayYear)
	out.WriteString(style(padOrTrim(header, width), "1", "4"))
	out.WriteString("\n")
	for _, line := range topLines {
		out.WriteString(line)
		out.WriteString("\n")
	}
	for _, line := range previewLines {
		out.WriteString(line)
		out.WriteString("\n")
	}
	return out.String()
}

func (app *App) renderMenuBox(title string, width, height int, items []MenuItem, selected int, focused bool) []string {
	if height < 3 {
		height = 3
	}
	lines := make([]string, 0, height)
	lines = append(lines, boxTopBorder(title, width))
	innerWidth := width - 2
	bodyLines := height - 2
	for index := 0; index < bodyLines; index++ {
		raw := ""
		if index < len(items) {
			item := items[index]
			prefix := " "
			if index == selected {
				prefix = ">"
			}
			if item.Count > 0 {
				raw = fmt.Sprintf("%s%2d %s", prefix, item.Count, item.Label)
			} else {
				raw = fmt.Sprintf("%s %s", prefix, item.Label)
			}
			if index == selected && focused {
				raw = style(padOrTrim(raw, innerWidth), "7")
				lines = append(lines, "│"+raw+"│")
				continue
			}
		}
		lines = append(lines, "│"+padOrTrim(raw, innerWidth)+"│")
	}
	lines = append(lines, boxBottomBorder(width))
	return lines
}

func (app *App) renderEventsBox(width, height int) []string {
	lines := make([]string, 0, height)
	lines = append(lines, boxTopBorder("Events", width))
	innerWidth := width - 2
	bodyLines := height - 2
	content := app.eventLines(innerWidth)
	for index := 0; index < bodyLines; index++ {
		value := ""
		if index < len(content) {
			value = content[index]
		}
		lines = append(lines, "│"+padOrTrim(value, innerWidth)+"│")
	}
	lines = append(lines, boxBottomBorder(width))
	return lines
}

func (app *App) eventLines(width int) []string {
	var lines []string
	today := time.Now().In(time.Local)
	for _, group := range app.cfg.Events {
		lines = append(lines, group.Name)
		for _, event := range group.Events {
			line := fmt.Sprintf(" - %s %02d.%02d.", event.Name, event.Day, event.Month)
			if suffix := app.eventDistanceSuffix(today, event); suffix != "" {
				line += suffix
			}
			lines = append(lines, padOrTrim(line, width))
		}
	}
	return lines
}

func (app *App) eventDistanceSuffix(today time.Time, event AnnualEvent) string {
	current := time.Date(today.Year(), time.Month(event.Month), event.Day, 12, 0, 0, 0, time.Local)
	if current.Before(time.Date(today.Year(), today.Month(), today.Day(), 12, 0, 0, 0, time.Local)) {
		current = current.AddDate(1, 0, 0)
	}
	delta := int(current.Sub(time.Date(today.Year(), today.Month(), today.Day(), 12, 0, 0, 0, time.Local)).Hours() / 24)
	if delta <= app.cfg.RecentEventsWindow {
		return fmt.Sprintf(" (in %d days)", delta)
	}

	previous := current.AddDate(-1, 0, 0)
	ago := int(time.Date(today.Year(), today.Month(), today.Day(), 12, 0, 0, 0, time.Local).Sub(previous).Hours() / 24)
	if ago <= app.cfg.RecentEventsWindow {
		return fmt.Sprintf(" (%d days ago)", ago)
	}
	return ""
}

func (app *App) renderCalendarArea(width, height int) []string {
	if width < 44 {
		width = 44
	}
	rows := 3
	rowHeight := maxInt(6, height/rows)
	monthWidth := maxInt(10, (width-3)/4)
	var lines []string
	title := fmt.Sprintf("%d", app.displayYear)
	lines = append(lines, boxTopBorder(title, width))
	for row := 0; row < rows; row++ {
		monthLines := [][]string{}
		for col := 0; col < 4; col++ {
			month := time.Month(row*4 + col + 1)
			monthLines = append(monthLines, app.renderMonth(month, monthWidth, rowHeight-1))
		}
		lines = append(lines, joinHorizontalWithGaps(monthLines, " ")...)
	}
	lines = append(lines, boxBottomBorder(width))
	return lines
}

func (app *App) renderMonth(month time.Month, width, height int) []string {
	if height < 5 {
		height = 5
	}
	lines := make([]string, 0, height)
	lines = append(lines, boxTopBorder(month.String(), width))
	weekdays := []string{"M", "T", "W", "T", "F", "S", "S"}
	if app.cfg.SundayStart {
		weekdays = []string{"S", "M", "T", "W", "T", "F", "S"}
	}
	lines = append(lines, "│"+padOrTrim(" "+strings.Join(weekdays, "  "), width-2)+"│")

	weeks := app.calendarWeeks(month)
	bodyRows := height - 3
	for row := 0; row < bodyRows; row++ {
		week := []string{"  ", "  ", "  ", "  ", "  ", "  ", "  "}
		if row < len(weeks) {
			week = weeks[row]
		}
		lines = append(lines, "│"+padOrTrim(strings.Join(week, " "), width-2)+"│")
	}
	lines = append(lines, boxBottomBorder(width))
	return lines
}

func (app *App) calendarWeeks(month time.Month) [][]string {
	first := time.Date(app.displayYear, month, 1, 12, 0, 0, 0, time.Local)
	offset := weekdayOffset(first.Weekday(), app.cfg.SundayStart)
	days := daysInMonth(app.displayYear, month)

	weeks := [][]string{}
	currentWeek := []string{"  ", "  ", "  ", "  ", "  ", "  ", "  "}
	slot := offset
	for day := 1; day <= days; day++ {
		date := time.Date(app.displayYear, month, day, 12, 0, 0, 0, time.Local)
		currentWeek[slot] = app.renderDayToken(date)
		slot++
		if slot == 7 {
			weeks = append(weeks, currentWeek)
			currentWeek = []string{"  ", "  ", "  ", "  ", "  ", "  ", "  "}
			slot = 0
		}
	}
	if slot != 0 {
		weeks = append(weeks, currentWeek)
	}
	return weeks
}

func (app *App) renderDayToken(date time.Time) string {
	token := fmt.Sprintf("%2d", date.Day())
	today := time.Now().In(time.Local)
	todayDate := time.Date(today.Year(), today.Month(), today.Day(), 12, 0, 0, 0, time.Local)
	isCursor := date.Equal(app.cursorDate) && !app.scratchpadMode
	hasLog := app.dateMatchesFilters(date)
	hasEvent := app.dateHasEvent(date.Month(), date.Day())

	switch {
	case isCursor:
		return style(token, "7")
	case date.Equal(todayDate):
		return style(token, "31")
	case hasEvent:
		return style(token, "32")
	case hasLog:
		return style(token, "33")
	case isWeekend(date.Weekday(), app.cfg.SundayStart):
		return style(token, "34")
	default:
		return token
	}
}

func (app *App) renderPreviewBox(width, height int) []string {
	title := fmt.Sprintf("log preview for %s.", shortDateString(app.cursorDate))
	lines := make([]string, 0, height)
	lines = append(lines, centeredBoxTopBorder(title, width))
	innerWidth := width - 2
	content := app.previewContent()
	wrapped := wrapLines(content, innerWidth)
	bodyLines := height - 2
	for index := 0; index < bodyLines; index++ {
		value := ""
		if index < len(wrapped) {
			value = wrapped[index]
		}
		lines = append(lines, "│"+padOrTrim(value, innerWidth)+"│")
	}
	lines = append(lines, boxBottomBorder(width))
	return lines
}

func (app *App) previewContent() string {
	if app.scratchpadMode {
		data, err := os.ReadFile(app.scratchpadPath())
		if err != nil {
			return ""
		}
		return string(data)
	}
	entry := app.repo.Entries[dateKey(app.cursorDate)]
	if entry == nil {
		return ""
	}
	return entry.Content
}

func (app *App) dateMatchesFilters(date time.Time) bool {
	entry := app.repo.Entries[dateKey(date)]
	if entry == nil {
		return false
	}
	section := app.selectedSectionValue()
	tag := app.selectedTagValue()
	if section == "" && tag == "" {
		return true
	}
	if tag != "" {
		for _, occurrence := range entry.TagOccurrences {
			if occurrence.Name != tag {
				continue
			}
			if section == "" || occurrence.Section == section {
				return true
			}
		}
		return false
	}
	if section != "" {
		_, ok := entry.SectionOccurrences[section]
		return ok
	}
	return false
}

func (app *App) dateHasEvent(month time.Month, day int) bool {
	for _, group := range app.cfg.Events {
		for _, event := range group.Events {
			if event.Month == int(month) && event.Day == day {
				return true
			}
		}
	}
	return false
}

func (app *App) logEntryCountForYear(year int) int {
	count := 0
	for _, date := range app.repo.Dates {
		if date.Year() == year {
			count++
		}
	}
	return count
}

func (app *App) currentLogPath() string {
	return filepath.Join(app.cfg.LogDirPath, app.format.Format(app.cursorDate))
}

func (app *App) scratchpadPath() string {
	return filepath.Join(app.cfg.ConfigDir, "scratchpad.md")
}

func (app *App) openEditor(path string) error {
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return err
	}
	if _, err := os.Stat(path); errors.Is(err, os.ErrNotExist) {
		initial := shortDateString(app.cursorDate) + ".\n"
		if app.scratchpadMode {
			initial = "# Scratchpad\n"
		}
		if err := os.WriteFile(path, []byte(initial), 0o644); err != nil {
			return err
		}
	}

	editor := os.Getenv("EDITOR")
	if strings.TrimSpace(editor) == "" {
		editor = "vi"
	}

	if app.screen != nil {
		if err := app.screen.Suspend(); err != nil {
			return err
		}
		defer app.screen.Resume()
	}

	command := fmt.Sprintf("%s %q", editor, path)
	return runCommand(command, nil, os.Stdin, os.Stdout, os.Stderr)
}

func (app *App) todayString() string {
	now := time.Now().In(time.Local)
	return now.Format("02. 01. 2006")
}

type TerminalSession struct {
	fd       int
	stdout   *os.File
	original *syscall.Termios
	active   bool
}

func NewTerminalSession(fd int, stdout *os.File) (*TerminalSession, error) {
	original, err := makeRaw(fd)
	if err != nil {
		return nil, err
	}
	session := &TerminalSession{
		fd:       fd,
		stdout:   stdout,
		original: original,
		active:   true,
	}
	fmt.Fprint(stdout, "\x1b[?1049h\x1b[?7l\x1b[?1000h\x1b[?1003h\x1b[?1015h\x1b[?1006h\x1b[?25l")
	return session, nil
}

func (session *TerminalSession) Draw(frame string) error {
	_, err := fmt.Fprint(session.stdout, "\x1b[2J\x1b[H"+frame)
	return err
}

func (session *TerminalSession) Suspend() error {
	if !session.active {
		return nil
	}
	if err := restoreTerminal(session.fd, session.original); err != nil {
		return err
	}
	fmt.Fprint(session.stdout, "\x1b[?1006l\x1b[?1015l\x1b[?1003l\x1b[?1000l\x1b[?7h\x1b[?1049l\x1b[?25h")
	session.active = false
	return nil
}

func (session *TerminalSession) Resume() error {
	if session.active {
		return nil
	}
	if _, err := makeRaw(session.fd); err != nil {
		return err
	}
	fmt.Fprint(session.stdout, "\x1b[?1049h\x1b[?7l\x1b[?1000h\x1b[?1003h\x1b[?1015h\x1b[?1006h\x1b[?25l")
	session.active = true
	return nil
}

func (session *TerminalSession) Close() error {
	if session == nil {
		return nil
	}
	if session.active {
		_ = restoreTerminal(session.fd, session.original)
		fmt.Fprint(session.stdout, "\x1b[?1006l\x1b[?1015l\x1b[?1003l\x1b[?1000l\x1b[?7h\x1b[?1049l\x1b[?25h")
		session.active = false
	}
	return nil
}

func (session *TerminalSession) Size() (int, int) {
	ws, err := getWinsize(session.fd)
	if err != nil {
		return 120, 30
	}
	return int(ws.Col), int(ws.Row)
}

type KeyKind int

const (
	KeyUnknown KeyKind = iota
	KeyUp
	KeyDown
	KeyLeft
	KeyRight
	KeyEnter
	KeyTab
	KeyBackTab
	KeyCtrlC
	KeyQuit
	KeyDelete
	KeyToggleScratchpad
	KeyNextYear
	KeyPrevYear
	KeyResetToday
)

type Key struct {
	Kind KeyKind
}

func readKey(reader *bufio.Reader) (Key, error) {
	value, err := reader.ReadByte()
	if err != nil {
		return Key{}, err
	}

	switch value {
	case 3:
		return Key{Kind: KeyCtrlC}, nil
	case '\r', '\n':
		return Key{Kind: KeyEnter}, nil
	case '\t':
		return Key{Kind: KeyTab}, nil
	case '+':
		return Key{Kind: KeyNextYear}, nil
	case '-':
		return Key{Kind: KeyPrevYear}, nil
	case 'q', 'Q':
		return Key{Kind: KeyQuit}, nil
	case 'd', 'D':
		return Key{Kind: KeyDelete}, nil
	case 's', 'S':
		return Key{Kind: KeyToggleScratchpad}, nil
	case 'r', 'R':
		return Key{Kind: KeyResetToday}, nil
	case 'h':
		return Key{Kind: KeyLeft}, nil
	case 'j':
		return Key{Kind: KeyDown}, nil
	case 'k':
		return Key{Kind: KeyUp}, nil
	case 'l':
		return Key{Kind: KeyRight}, nil
	case 0x1b:
		time.Sleep(5 * time.Millisecond)
		if reader.Buffered() == 0 {
			return Key{Kind: KeyUnknown}, nil
		}
		next, _ := reader.ReadByte()
		if next != '[' {
			return Key{Kind: KeyUnknown}, nil
		}
		final, _ := reader.ReadByte()
		switch final {
		case 'A':
			return Key{Kind: KeyUp}, nil
		case 'B':
			return Key{Kind: KeyDown}, nil
		case 'C':
			return Key{Kind: KeyRight}, nil
		case 'D':
			return Key{Kind: KeyLeft}, nil
		case 'Z':
			return Key{Kind: KeyBackTab}, nil
		}
	}

	return Key{Kind: KeyUnknown}, nil
}

func makeRaw(fd int) (*syscall.Termios, error) {
	state, err := tcget(fd)
	if err != nil {
		return nil, err
	}
	raw := *state
	raw.Iflag &^= syscall.IGNBRK | syscall.BRKINT | syscall.PARMRK | syscall.ISTRIP | syscall.INLCR | syscall.IGNCR | syscall.ICRNL | syscall.IXON
	raw.Oflag &^= syscall.OPOST
	raw.Lflag &^= syscall.ECHO | syscall.ECHONL | syscall.ICANON | syscall.ISIG | syscall.IEXTEN
	raw.Cflag &^= syscall.CSIZE | syscall.PARENB
	raw.Cflag |= syscall.CS8
	raw.Cc[syscall.VMIN] = 1
	raw.Cc[syscall.VTIME] = 0
	if err := tcset(fd, &raw); err != nil {
		return nil, err
	}
	return state, nil
}

func restoreTerminal(fd int, state *syscall.Termios) error {
	if state == nil {
		return nil
	}
	return tcset(fd, state)
}

func tcget(fd int) (*syscall.Termios, error) {
	state := &syscall.Termios{}
	_, _, errno := syscall.Syscall6(syscall.SYS_IOCTL, uintptr(fd), uintptr(syscall.TCGETS), uintptr(unsafe.Pointer(state)), 0, 0, 0)
	if errno != 0 {
		return nil, errno
	}
	return state, nil
}

func tcset(fd int, state *syscall.Termios) error {
	_, _, errno := syscall.Syscall6(syscall.SYS_IOCTL, uintptr(fd), uintptr(syscall.TCSETS), uintptr(unsafe.Pointer(state)), 0, 0, 0)
	if errno != 0 {
		return errno
	}
	return nil
}

type winsize struct {
	Row    uint16
	Col    uint16
	Xpixel uint16
	Ypixel uint16
}

func getWinsize(fd int) (*winsize, error) {
	ws := &winsize{}
	_, _, errno := syscall.Syscall6(syscall.SYS_IOCTL, uintptr(fd), uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(ws)), 0, 0, 0)
	if errno != 0 {
		return nil, errno
	}
	return ws, nil
}

func isTerminal(fd uintptr) bool {
	_, err := tcget(int(fd))
	return err == nil
}

func boxTopBorder(title string, width int) string {
	if width < 2 {
		return ""
	}
	innerWidth := width - 2
	return "╭" + padOrTrim(title, innerWidth, '─') + "╮"
}

func centeredBoxTopBorder(title string, width int) string {
	if width < 2 {
		return ""
	}
	innerWidth := width - 2
	title = padOrTrim(title, minInt(innerWidth, visibleWidth(title)))
	remaining := innerWidth - visibleWidth(title)
	left := remaining / 2
	right := remaining - left
	return "╭" + strings.Repeat("─", left) + title + strings.Repeat("─", right) + "╮"
}

func boxBottomBorder(width int) string {
	if width < 2 {
		return ""
	}
	return "╰" + strings.Repeat("─", width-2) + "╯"
}

func padOrTrim(value string, width int, fill ...rune) string {
	fillRune := ' '
	if len(fill) > 0 {
		fillRune = fill[0]
	}
	if width <= 0 {
		return ""
	}
	if visibleWidth(value) > width {
		return trimVisible(value, width)
	}
	return value + strings.Repeat(string(fillRune), width-visibleWidth(value))
}

func trimVisible(value string, width int) string {
	if width <= 0 {
		return ""
	}
	if visibleWidth(value) <= width {
		return value
	}
	var out bytes.Buffer
	count := 0
	for _, r := range value {
		if count == width {
			break
		}
		out.WriteRune(r)
		count++
	}
	return out.String()
}

func visibleWidth(value string) int {
	return utf8.RuneCountInString(value)
}

func style(value string, codes ...string) string {
	return "\x1b[" + strings.Join(codes, ";") + "m" + value + "\x1b[0m"
}

func joinHorizontal(left, right []string) []string {
	return joinHorizontalWithGaps([][]string{left, right}, " ")
}

func joinHorizontalWithGaps(parts [][]string, gap string) []string {
	maxLines := 0
	for _, part := range parts {
		if len(part) > maxLines {
			maxLines = len(part)
		}
	}

	widths := make([]int, len(parts))
	for index, part := range parts {
		for _, line := range part {
			if visibleWidth(line) > widths[index] {
				widths[index] = visibleWidth(line)
			}
		}
	}

	lines := make([]string, 0, maxLines)
	for row := 0; row < maxLines; row++ {
		var chunks []string
		for index, part := range parts {
			line := ""
			if row < len(part) {
				line = part[row]
			}
			chunks = append(chunks, padOrTrim(line, widths[index]))
		}
		lines = append(lines, strings.Join(chunks, gap))
	}
	return lines
}

func wrapLines(text string, width int) []string {
	if width <= 0 {
		return nil
	}
	if text == "" {
		return nil
	}
	var wrapped []string
	for _, line := range strings.Split(strings.ReplaceAll(text, "\r\n", "\n"), "\n") {
		remaining := line
		for visibleWidth(remaining) > width {
			wrapped = append(wrapped, trimVisible(remaining, width))
			runes := []rune(remaining)
			remaining = string(runes[minInt(len(runes), width):])
		}
		wrapped = append(wrapped, remaining)
	}
	return wrapped
}

func shortDateString(date time.Time) string {
	return date.Format("02. 01. 06")
}

func weekdayOffset(weekday time.Weekday, sundayStart bool) int {
	if sundayStart {
		return int(weekday)
	}
	if weekday == time.Sunday {
		return 6
	}
	return int(weekday) - 1
}

func daysInMonth(year int, month time.Month) int {
	return time.Date(year, month+1, 0, 12, 0, 0, 0, time.Local).Day()
}

func minInt(values ...int) int {
	result := values[0]
	for _, value := range values[1:] {
		if value < result {
			result = value
		}
	}
	return result
}

func maxInt(values ...int) int {
	result := values[0]
	for _, value := range values[1:] {
		if value > result {
			result = value
		}
	}
	return result
}

func isWeekend(day time.Weekday, sundayStart bool) bool {
	if sundayStart {
		return day == time.Saturday || day == time.Sunday
	}
	return day == time.Saturday || day == time.Sunday
}

