package main

import (
	"bufio"
	"bytes"
	"crypto/aes"
	"crypto/cipher"
	"crypto/md5"
	"errors"
	"fmt"
	"io/fs"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
)

const (
	versionString         = "commit-93cc85d16ab60ba8d646458fe0233778317b22a3"
	defaultLogNameFormat  = "d%y_%m_%d.md"
	encryptionMarkerPlain = "encryption-marker:"
	markerFileName        = ".cle"
	rootSectionLabel      = "<root section>"
	selectNoneLabel       = "<select none>"
)

type CLIOptions struct {
	Help             bool
	ConfigPath       string
	LogDirPath       string
	LogNameFormat    string
	SundayStart      bool
	FirstLineSection bool
	Password         string
	Encrypt          bool
	Decrypt          bool
}

func main() {
	home, err := os.UserHomeDir()
	if err != nil || home == "" {
		home = "/"
	}

	opts, err := parseCLI(os.Args[1:])
	if err != nil {
		fatalError(err.Error())
	}
	if opts.Help {
		fmt.Fprint(os.Stdout, helpText(defaultConfigPath(home)))
		return
	}

	configPath := opts.ConfigPath
	if configPath == "" {
		configPath = defaultConfigPath(home)
	}
	configPath, err = expandPath(configPath, home)
	if err != nil {
		fatalError(err.Error())
	}

	iniFile, err := loadINIFile(configPath)
	if err != nil {
		fatalError("Failed to open file: " + configPath)
	}

	cfg, err := buildConfig(home, configPath, iniFile, opts)
	if err != nil {
		fatalError(err.Error())
	}

	if opts.Encrypt || opts.Decrypt {
		if opts.Encrypt {
			if cfg.Password == "" {
				fatalError("Password must be provided when encrypting logs!")
			}
			if err := encryptRepository(cfg.LogDirPath, cfg.Password); err != nil {
				fatalError(err.Error())
			}
			return
		}

		if cfg.Password == "" {
			fatalError("Password must be provided when decrypting logs!")
		}
		if err := decryptRepository(cfg.LogDirPath); err != nil {
			fatalError(err.Error())
		}
		return
	}

	if err := os.MkdirAll(cfg.LogDirPath, 0o755); err != nil {
		fatalError(err.Error())
	}

	encrypted, markerBytes, err := readRepositoryMarker(cfg.LogDirPath)
	if err != nil {
		fatalError(err.Error())
	}
	if encrypted {
		if cfg.Password == "" && isTerminal(os.Stdin.Fd()) {
			cfg.Password, err = promptPassword()
			if err != nil {
				fatalError(err.Error())
			}
		}
		if !validateMarker(markerBytes, cfg.Password) {
			fatalError("Invalid password provided!")
		}
	} else if cfg.Password != "" {
		fatalError("Password provided for a non encrypted repository!")
	}

	repo, err := ScanRepository(cfg)
	if err != nil {
		fatalError(err.Error())
	}

	app := NewApp(cfg, repo)
	if err := app.Run(); err != nil && !errors.Is(err, errAppExit) {
		fatalError(err.Error())
	}
}

func parseCLI(args []string) (CLIOptions, error) {
	var opts CLIOptions

	for i := 0; i < len(args); i++ {
		arg := args[i]
		switch {
		case arg == "-h" || arg == "--help":
			opts.Help = true
		case arg == "--sunday-start":
			opts.SundayStart = true
		case arg == "--first-line-section":
			opts.FirstLineSection = true
		case arg == "--encrypt":
			opts.Encrypt = true
		case arg == "--decrypt":
			opts.Decrypt = true
		case arg == "-c" || arg == "--config":
			value, next, err := requireOptionValue(args, i, arg)
			if err != nil {
				return CLIOptions{}, err
			}
			opts.ConfigPath = value
			i = next
		case strings.HasPrefix(arg, "--config="):
			opts.ConfigPath = strings.TrimPrefix(arg, "--config=")
		case arg == "--log-dir-path":
			value, next, err := requireOptionValue(args, i, arg)
			if err != nil {
				return CLIOptions{}, err
			}
			opts.LogDirPath = value
			i = next
		case strings.HasPrefix(arg, "--log-dir-path="):
			opts.LogDirPath = strings.TrimPrefix(arg, "--log-dir-path=")
		case arg == "--log-name-format":
			value, next, err := requireOptionValue(args, i, arg)
			if err != nil {
				return CLIOptions{}, err
			}
			opts.LogNameFormat = value
			i = next
		case strings.HasPrefix(arg, "--log-name-format="):
			opts.LogNameFormat = strings.TrimPrefix(arg, "--log-name-format=")
		case arg == "--password":
			value, next, err := requireOptionValue(args, i, arg)
			if err != nil {
				return CLIOptions{}, err
			}
			opts.Password = value
			i = next
		case strings.HasPrefix(arg, "--password="):
			opts.Password = strings.TrimPrefix(arg, "--password=")
		case strings.HasPrefix(arg, "-"):
			return CLIOptions{}, fmt.Errorf("unrecognised option '%s'", arg)
		default:
			return CLIOptions{}, fmt.Errorf("too many positional options have been specified on the command line")
		}
	}

	return opts, nil
}

func requireOptionValue(args []string, index int, flag string) (string, int, error) {
	if index+1 >= len(args) {
		return "", index, fmt.Errorf("the required argument for option '%s' is missing", flag)
	}
	return args[index+1], index + 1, nil
}

func helpText(configPath string) string {
	return fmt.Sprintf(`Captain's Log (caps-log)! A CLI journalig tool.
Version: %s
Allowed options:
  -h [ --help ]         show this message
  -c [ --config ] arg   override the default config file path 
                        (%s)
  --log-dir-path arg    path where log files are stored
  --log-name-format arg format in which log entry markdown files are saved
  --sunday-start        have the calendar display sunday as first day of the 
                        week
  --first-line-section  override the default behaviour of ignoring sections 
                        (lines starting with `+"`#`"+`) in the first line of a log 
                        entry file
  --password arg        password for encrypted log repositories or to be used 
                        with --encrypt/--decrypt
  --encrypt             apply encryption to all logs in log dir path (needs 
                        --password)
  --decrypt             apply decryption to all logs in log dir path (needs 
                        --password)
`, versionString, configPath)
}

func defaultConfigPath(home string) string {
	return filepath.Join(home, ".caps-log", "config.ini")
}

func defaultLogDirPath(home string) string {
	return filepath.Join(home, ".caps-log", "day")
}

func expandPath(path, home string) (string, error) {
	if path == "" {
		return "", nil
	}
	if path == "~" {
		return home, nil
	}
	if strings.HasPrefix(path, "~/") {
		return filepath.Join(home, path[2:]), nil
	}
	return filepath.Abs(path)
}

func promptPassword() (string, error) {
	fmt.Fprint(os.Stdout, "Password: ")
	reader := bufio.NewReader(os.Stdin)
	line, err := reader.ReadString('\n')
	fmt.Fprintln(os.Stdout)
	if err != nil && !errors.Is(err, os.ErrClosed) && !errors.Is(err, fs.ErrClosed) {
		return "", err
	}
	return strings.TrimRight(line, "\r\n"), nil
}

func encryptRepository(logDirPath, password string) error {
	fmt.Fprintln(os.Stdout, "Applying crypto...")
	if err := ensureReadableDirectory(logDirPath); err != nil {
		return err
	}
	markerPath := filepath.Join(logDirPath, markerFileName)
	if _, err := os.Stat(markerPath); err == nil {
		return errors.New("Already applied")
	} else if !errors.Is(err, fs.ErrNotExist) {
		return err
	}
	return os.WriteFile(markerPath, buildMarker(password), 0o600)
}

func decryptRepository(logDirPath string) error {
	fmt.Fprintln(os.Stdout, "Applying crypto...")
	if err := ensureReadableDirectory(logDirPath); err != nil {
		return err
	}
	markerPath := filepath.Join(logDirPath, markerFileName)
	if _, err := os.Stat(markerPath); errors.Is(err, fs.ErrNotExist) {
		return errors.New("Already applied")
	} else if err != nil {
		return err
	}
	return os.Remove(markerPath)
}

func ensureReadableDirectory(path string) error {
	if _, err := os.ReadDir(path); err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return fmt.Errorf("filesystem error: directory iterator cannot open directory: No such file or directory [%s]", path)
		}
		return fmt.Errorf("filesystem error: directory iterator cannot open directory: %s [%s]", err.Error(), path)
	}
	return nil
}

func readRepositoryMarker(logDirPath string) (bool, []byte, error) {
	markerPath := filepath.Join(logDirPath, markerFileName)
	data, err := os.ReadFile(markerPath)
	if errors.Is(err, fs.ErrNotExist) {
		return false, nil, nil
	}
	if err != nil {
		return false, nil, err
	}
	return true, data, nil
}

func buildMarker(password string) []byte {
	key, iv := evpBytesToKeyMD5([]byte(password), 16, aes.BlockSize)
	block, err := aes.NewCipher(key)
	if err != nil {
		panic(err)
	}
	plaintext := []byte(encryptionMarkerPlain)
	ciphertext := make([]byte, len(plaintext))
	cipher.NewCFBEncrypter(block, iv).XORKeyStream(ciphertext, plaintext)
	return ciphertext
}

func validateMarker(marker []byte, password string) bool {
	if password == "" || len(marker) != len(encryptionMarkerPlain) {
		return false
	}
	key, iv := evpBytesToKeyMD5([]byte(password), 16, aes.BlockSize)
	block, err := aes.NewCipher(key)
	if err != nil {
		return false
	}
	plaintext := make([]byte, len(marker))
	cipher.NewCFBDecrypter(block, iv).XORKeyStream(plaintext, marker)
	return bytes.Equal(plaintext, []byte(encryptionMarkerPlain))
}

func evpBytesToKeyMD5(password []byte, keyLen, ivLen int) ([]byte, []byte) {
	var material []byte
	var prev []byte
	for len(material) < keyLen+ivLen {
		hash := md5.New()
		hash.Write(prev)
		hash.Write(password)
		prev = hash.Sum(nil)
		material = append(material, prev...)
	}
	return material[:keyLen], material[keyLen : keyLen+ivLen]
}

func fatalError(message string) {
	fmt.Fprintf(os.Stderr, "Captain's log encountered an error: \n %s\n", message)
	os.Exit(1)
}

func runCommand(command string, extraEnv map[string]string, stdin, stdout, stderr *os.File) error {
	cmd := exec.Command("sh", "-lc", command)
	cmd.Stdin = stdin
	cmd.Stdout = stdout
	cmd.Stderr = stderr
	if len(extraEnv) > 0 {
		env := os.Environ()
		for key, value := range extraEnv {
			env = append(env, key+"="+value)
		}
		cmd.Env = env
	}
	return cmd.Run()
}

