package main

import (
	"bufio"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"time"
)

type Config struct {
	ConfigPath        string
	ConfigDir         string
	LogDirPath        string
	LogNameFormat     string
	SundayStart       bool
	FirstLineSection  bool
	Password          string
	Git               GitConfig
	Events            []EventGroup
	RecentEventsWindow int
}

type GitConfig struct {
	Enabled       bool
	SSHKeyPath    string
	SSHPubKeyPath string
	RepoRoot      string
	RemoteName    string
	MainBranch    string
}

type EventGroup struct {
	Name   string
	Events []AnnualEvent
}

type AnnualEvent struct {
	Group string
	Name  string
	Month int
	Day   int
}

type INIFile struct {
	Root         map[string]string
	Sections     map[string]map[string]string
	SectionOrder []string
}

type Repository struct {
	Entries map[string]*LogEntry
	Dates   []time.Time
}

type LogEntry struct {
	Date              time.Time
	Path              string
	Content           string
	SectionOccurrences map[string]int
	TagOccurrences    []TagOccurrence
}

type TagOccurrence struct {
	Section string
	Name    string
}

type MenuItem struct {
	Label string
	Count int
	Value string
}

type LogNameFormat struct {
	raw       string
	goLayout  string
	regex     *regexp.Regexp
	tokens    []formatToken
}

type formatToken struct {
	Literal string
	Name    string
}

func loadINIFile(path string) (*INIFile, error) {
	file, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer file.Close()

	ini := &INIFile{
		Root:     map[string]string{},
		Sections: map[string]map[string]string{},
	}

	currentSection := ""
	scanner := bufio.NewScanner(file)
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" || strings.HasPrefix(line, "#") || strings.HasPrefix(line, ";") {
			continue
		}
		if strings.HasPrefix(line, "[") && strings.HasSuffix(line, "]") {
			currentSection = strings.ToLower(strings.TrimSpace(line[1 : len(line)-1]))
			if _, ok := ini.Sections[currentSection]; !ok {
				ini.Sections[currentSection] = map[string]string{}
				ini.SectionOrder = append(ini.SectionOrder, currentSection)
			}
			continue
		}

		parts := strings.SplitN(line, "=", 2)
		if len(parts) != 2 {
			continue
		}

		key := strings.ToLower(strings.TrimSpace(parts[0]))
		value := stripInlineComment(strings.TrimSpace(parts[1]))
		if currentSection == "" {
			ini.Root[key] = value
		} else {
			ini.Sections[currentSection][key] = value
		}
	}

	if err := scanner.Err(); err != nil {
		return nil, err
	}
	return ini, nil
}

func buildConfig(home, configPath string, ini *INIFile, opts CLIOptions) (Config, error) {
	configDir := filepath.Dir(configPath)
	cfg := Config{
		ConfigPath:         configPath,
		ConfigDir:          configDir,
		LogDirPath:         defaultLogDirPath(home),
		LogNameFormat:      defaultLogNameFormat,
		RecentEventsWindow: 60,
		Git: GitConfig{
			RemoteName: "origin",
			MainBranch: "master",
		},
	}

	if value := firstNonEmpty(ini.Root["log-dir-path"], ini.Root["logdir"]); value != "" {
		path, err := expandPath(value, home)
		if err != nil {
			return Config{}, err
		}
		cfg.LogDirPath = path
	}
	if value := firstNonEmpty(ini.Root["log-name-format"], ini.Root["log-filename-format"]); value != "" {
		cfg.LogNameFormat = value
	}
	if value, ok := ini.Root["sunday-start"]; ok {
		cfg.SundayStart = parseBool(value)
	}
	if value, ok := ini.Root["first-line-section"]; ok {
		cfg.FirstLineSection = parseBool(value)
	}
	if value, ok := ini.Root["password"]; ok {
		cfg.Password = value
	}

	if section, ok := ini.Sections["git"]; ok {
		cfg.Git.Enabled = parseBool(section["enable-git-log-repo"])
		if cfg.Git.Enabled {
			if value := section["ssh-key-path"]; value != "" {
				path, err := expandPath(value, home)
				if err != nil {
					return Config{}, err
				}
				cfg.Git.SSHKeyPath = path
			}
			if value := section["ssh-pub-key-path"]; value != "" {
				path, err := expandPath(value, home)
				if err != nil {
					return Config{}, err
				}
				cfg.Git.SSHPubKeyPath = path
			}
			if value := section["repo-root"]; value != "" {
				path, err := expandPath(value, home)
				if err != nil {
					return Config{}, err
				}
				cfg.Git.RepoRoot = path
			}
			if value := section["remote-name"]; value != "" {
				cfg.Git.RemoteName = value
			}
			if value := section["main-branch-name"]; value != "" {
				cfg.Git.MainBranch = value
			}
		}
	}

	if section, ok := ini.Sections["calendar-events"]; ok {
		if value := section["recent-events-window"]; value != "" {
			if parsed, err := strconv.Atoi(value); err == nil {
				cfg.RecentEventsWindow = parsed
			}
		}
	}
	cfg.Events = parseAnnualEvents(ini)

	if opts.LogDirPath != "" {
		path, err := expandPath(opts.LogDirPath, home)
		if err != nil {
			return Config{}, err
		}
		cfg.LogDirPath = path
	}
	if opts.LogNameFormat != "" {
		cfg.LogNameFormat = opts.LogNameFormat
	}
	if opts.SundayStart {
		cfg.SundayStart = true
	}
	if opts.FirstLineSection {
		cfg.FirstLineSection = true
	}
	if opts.Password != "" {
		cfg.Password = opts.Password
	}

	if cfg.Git.Enabled && cfg.Git.RepoRoot != "" {
		rel, err := filepath.Rel(cfg.Git.RepoRoot, cfg.LogDirPath)
		if err != nil || strings.HasPrefix(rel, "..") {
			return Config{}, fmt.Errorf("log-dir-path must be inside git.repo-root")
		}
	}

	return cfg, nil
}

func stripInlineComment(value string) string {
	for _, marker := range []string{" #", " ;"} {
		if index := strings.Index(value, marker); index >= 0 {
			return strings.TrimSpace(value[:index])
		}
	}
	return strings.TrimSpace(value)
}

func parseBool(value string) bool {
	switch strings.ToLower(strings.TrimSpace(value)) {
	case "1", "true", "yes", "on":
		return true
	default:
		return false
	}
}

func firstNonEmpty(values ...string) string {
	for _, value := range values {
		if value != "" {
			return value
		}
	}
	return ""
}

func parseAnnualEvents(ini *INIFile) []EventGroup {
	groups := map[string][]AnnualEvent{}
	order := []string{}
	for _, name := range ini.SectionOrder {
		if !strings.HasPrefix(name, "calendar-events.") {
			continue
		}
		parts := strings.Split(name, ".")
		if len(parts) != 3 {
			continue
		}
		groupName := normalizeEventGroupName(parts[1])
		section := ini.Sections[name]
		eventName := section["name"]
		dateValue := strings.TrimSuffix(section["date"], ".")
		pieces := strings.Split(dateValue, ".")
		if len(pieces) != 2 {
			continue
		}
		day, dayErr := strconv.Atoi(strings.TrimSpace(pieces[0]))
		month, monthErr := strconv.Atoi(strings.TrimSpace(pieces[1]))
		if dayErr != nil || monthErr != nil {
			continue
		}
		if _, ok := groups[groupName]; !ok {
			order = append(order, groupName)
		}
		groups[groupName] = append(groups[groupName], AnnualEvent{
			Group: groupName,
			Name:  eventName,
			Month: month,
			Day:   day,
		})
	}

	var eventGroups []EventGroup
	for _, groupName := range order {
		items := groups[groupName]
		sort.Slice(items, func(i, j int) bool {
			if items[i].Month != items[j].Month {
				return items[i].Month < items[j].Month
			}
			if items[i].Day != items[j].Day {
				return items[i].Day < items[j].Day
			}
			return items[i].Name < items[j].Name
		})
		eventGroups = append(eventGroups, EventGroup{Name: groupName, Events: items})
	}
	return eventGroups
}

func normalizeEventGroupName(name string) string {
	if name == "birthadays" {
		return "birthdays"
	}
	return name
}

func ScanRepository(cfg Config) (*Repository, error) {
	format, err := compileLogNameFormat(cfg.LogNameFormat)
	if err != nil {
		return nil, err
	}
	repo := &Repository{Entries: map[string]*LogEntry{}}

	dirEntries, err := os.ReadDir(cfg.LogDirPath)
	if err != nil {
		return repo, nil
	}

	for _, dirEntry := range dirEntries {
		if dirEntry.IsDir() {
			continue
		}
		date, ok := format.Parse(dirEntry.Name())
		if !ok {
			continue
		}
		path := filepath.Join(cfg.LogDirPath, dirEntry.Name())
		contentBytes, err := os.ReadFile(path)
		if err != nil {
			continue
		}
		entry := parseLogEntry(date, path, string(contentBytes), cfg.FirstLineSection)
		repo.Entries[dateKey(date)] = entry
		repo.Dates = append(repo.Dates, date)
	}

	sort.Slice(repo.Dates, func(i, j int) bool {
		return repo.Dates[i].Before(repo.Dates[j])
	})
	return repo, nil
}

func parseLogEntry(date time.Time, path, content string, firstLineSection bool) *LogEntry {
	entry := &LogEntry{
		Date:               date,
		Path:               path,
		Content:            content,
		SectionOccurrences: map[string]int{},
	}

	currentSection := ""
