			regex.WriteString("(\\d{2})")
			tokens = append(tokens, formatToken{Name: "y"})
		case 'm':
			layout.WriteString("01")
			regex.WriteString("(\\d{2})")
			tokens = append(tokens, formatToken{Name: "m"})
		case 'd':
			layout.WriteString("02")
			regex.WriteString("(\\d{2})")
			tokens = append(tokens, formatToken{Name: "d"})
		default:
			layout.WriteByte('%')
			layout.WriteByte(raw[index])
			regex.WriteString(regexp.QuoteMeta("%" + string(raw[index])))
		}
	}

	regex.WriteString("$")
	compiled, err := regexp.Compile(regex.String())
	if err != nil {
		return LogNameFormat{}, err
	}

