		raw:      raw,
		goLayout: layout.String(),
		regex:    compiled,
		tokens:   tokens,
	}, nil
}

func (format LogNameFormat) Format(date time.Time) string {
	return date.Format(format.goLayout)
}

func (format LogNameFormat) Parse(name string) (time.Time, bool) {
	matches := format.regex.FindStringSubmatch(name)
	if matches == nil {
		return time.Time{}, false
	}

	year := 0
	month := 1
	day := 1
	groupIndex := 1
	for _, token := range format.tokens {
		value := matches[groupIndex]
		groupIndex++
		switch token.Name {
